import { BrowserRouter,Navigate,Route,Routes } from 'react-router-dom';import { useEffect } from 'react';import { usePatientAuthStore } from '../store/authStore';import { ProtectedRoute } from '../routes/ProtectedRoute';import { PatientShell } from '../layouts/PatientShell';import { Account,AppointmentDetail,Appointments,Book,Dashboard,DoctorSlots,Features,HospitalDetails,Hospitals,Landing,Login,Medical,NotFound,Profile,RecordDetail,Records,Register,Settings,Teleconsult,Trust,Unauthorized } from '../pages/Pages';
function Boot(){const restore=usePatientAuthStore(s=>s.restoreSession);useEffect(()=>restore(),[restore]);return null}
export function App(){return <BrowserRouter><Boot/><Routes><Route path="/" element={<Landing/>}/><Route path="/features" element={<Features/>}/><Route path="/trust" element={<Trust/>}/><Route path="/login" element={<Login/>}/><Route path="/register" element={<Register/>}/><Route path="/unauthorized" element={<Unauthorized/>}/><Route element={<ProtectedRoute/>}><Route path="/app" element={<PatientShell/>}><Route index element={<Navigate to="/app/dashboard" replace/>}/><Route path="dashboard" element={<Dashboard/>}/><Route path="profile" element={<Profile/>}/><Route path="medical-basics" element={<Medical/>}/><Route path="hospitals" element={<Hospitals/>}/><Route path="hospitals/:hospitalId" element={<HospitalDetails/>}/><Route path="hospitals/:hospitalId/doctors" element={<HospitalDetails/>}/><Route path="doctors/:hospitalDoctorId/slots" element={<DoctorSlots/>}/><Route path="book/:hospitalDoctorId" element={<Book/>}/><Route path="appointments" element={<Appointments/>}/><Route path="appointments/:id" element={<AppointmentDetail/>}/><Route path="records" element={<Records/>}/><Route path="records/:encounterId" element={<RecordDetail/>}/><Route path="teleconsult/:appointmentId" element={<Teleconsult/>}/><Route path="settings" element={<Settings/>}/><Route path="account" element={<Account/>}/></Route></Route><Route path="*" element={<NotFound/>}/></Routes></BrowserRouter>}
